import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv2d_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv2d_naive_kernel(
    const float* input, 
    const float* weight, 
    const float* bias, 
    float* output,
    int N,
    int C_in,
    int H_in,
    int W_in,
    int C_out,
    int H_out,
    int W_out,
    int kernel_h,
    int kernel_w,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int dilation_h,
    int dilation_w,
    bool has_bias)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C_out * H_out * W_out;
    if(idx >= total) return;

    int ow = idx % W_out;
    int oh = (idx / W_out) % H_out;
    int oc = (idx / (W_out * H_out)) % C_out;
    int n  = idx / (C_out * H_out * W_out);

    float val = 0.0f;
    for(int ic = 0; ic < C_in; ic++){
        for(int kh = 0; kh < kernel_h; kh++){
            for(int kw = 0; kw < kernel_w; kw++){
                int in_h = oh * stride_h - pad_h + kh * dilation_h;
                int in_w = ow * stride_w - pad_w + kw * dilation_w;
                if(in_h >= 0 && in_h < H_in && in_w >= 0 && in_w < W_in){
                    int input_index = ((n * C_in + ic) * H_in + in_h) * W_in + in_w;
                    int weight_index = ((oc * C_in + ic) * kernel_h + kh) * kernel_w + kw;
                    val += input[input_index] * weight[weight_index];
                }
            }
        }
    }
    if(has_bias){
        val += bias[oc];
    }
    int out_index = ((n * C_out + oc) * H_out + oh) * W_out + ow;
    output[out_index] = val;
}

torch::Tensor conv2d_naive_cuda(
    torch::Tensor x, 
    torch::Tensor weight, 
    torch::Tensor bias,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int dilation_h,
    int dilation_w)
{
    int N = x.size(0);
    int C_in = x.size(1);
    int H_in = x.size(2);
    int W_in = x.size(3);

    int C_out = weight.size(0);
    int kernel_h = weight.size(2);
    int kernel_w = weight.size(3);

    int H_out = (H_in + 2*pad_h - dilation_h*(kernel_h - 1) - 1) / stride_h + 1;
    int W_out = (W_in + 2*pad_w - dilation_w*(kernel_w - 1) - 1) / stride_w + 1;

    auto options = x.options();
    auto out = torch::zeros({N, C_out, H_out, W_out}, options);

    x = x.contiguous();
    weight = weight.contiguous();
    bool has_bias = bias.defined();
    if(has_bias) bias = bias.contiguous();

    int total = N * C_out * H_out * W_out;
    int blockSize = 256;
    int gridSize = (total + blockSize - 1) / blockSize;

    conv2d_naive_kernel<<<gridSize, blockSize>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        out.data_ptr<float>(),
        N,
        C_in,
        H_in,
        W_in,
        C_out,
        H_out,
        W_out,
        kernel_h,
        kernel_w,
        stride_h,
        stride_w,
        pad_h,
        pad_w,
        dilation_h,
        dilation_w,
        has_bias
    );

    return out;
}
"""

conv2d_cpp_source = r"""
torch::Tensor conv2d_naive_cuda(
    torch::Tensor x, 
    torch::Tensor weight, 
    torch::Tensor bias,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int dilation_h,
    int dilation_w
);
"""

conv2d_naive = load_inline(
    name="conv2d_naive",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_source,
    functions=["conv2d_naive_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(
        self, 
        in_channels: int, 
        out_channels: int, 
        kernel_size: tuple, 
        stride: int = 1, 
        padding: int = 0, 
        dilation: int = 1, 
        groups: int = 1, 
        bias: bool = False
    ):
        super(ModelNew, self).__init__()
        assert groups == 1, "Custom conv2d kernel only supports groups=1."

        if isinstance(kernel_size, int):
            kernel_size = (kernel_size, kernel_size)
        self.kernel_h, self.kernel_w = kernel_size

        self.stride_h = stride if isinstance(stride, int) else stride[0]
        self.stride_w = stride if isinstance(stride, int) else stride[1] if len(stride) > 1 else stride[0]
        self.pad_h = padding if isinstance(padding, int) else padding[0]
        self.pad_w = padding if isinstance(padding, int) else padding[1] if len(padding) > 1 else padding[0]
        self.dilation_h = dilation if isinstance(dilation, int) else dilation[0]
        self.dilation_w = dilation if isinstance(dilation, int) else dilation[1] if len(dilation) > 1 else dilation[0]

        self.weight = nn.Parameter(torch.randn(out_channels, in_channels, self.kernel_h, self.kernel_w))
        self.bias = nn.Parameter(torch.zeros(out_channels)) if bias else None

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv2d_naive.conv2d_naive_cuda(
            x,
            self.weight,
            self.bias if self.bias is not None else torch.tensor([], device=x.device),
            self.stride_h,
            self.stride_w,
            self.pad_h,
            self.pad_w,
            self.dilation_h,
            self.dilation_w
        )
